import { FilterRegistry } from 'domain/Filter';
import { commercialResultsUrlFilterHandler } from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsUrlFilterHandler';
import { COMMERCIAL_RESULTS_PAGE_NAME } from 'pages/pillars/ValueCreation/CommercialResults/constants';

import type { PageUrlFilterHandler } from './types';

/**
 * Composition root for page-specific URL → Redux filter handlers.
 * Core `useFiltersUrlSync` delegates here; add new pages in this map only.
 */
const PAGE_URL_FILTER_HANDLERS: Record<string, PageUrlFilterHandler> = {
  [COMMERCIAL_RESULTS_PAGE_NAME]: commercialResultsUrlFilterHandler,
};

/** Canonical time-period keys that need legacy `periods` migration on CR. */
function hasTimePeriodMigrationParams(searchParams: URLSearchParams): boolean {
  const urlFilters = FilterRegistry.extractFiltersFromUrl(searchParams);

  return urlFilters.period_type != null || urlFilters.dt_end != null;
}

export function getPageUrlFilterHandler(
  pageName?: string,
  searchParams?: URLSearchParams,
): PageUrlFilterHandler | undefined {
  if (!pageName) return undefined;

  const handler = PAGE_URL_FILTER_HANDLERS[pageName];
  if (!handler) return undefined;

  if (
    pageName === COMMERCIAL_RESULTS_PAGE_NAME &&
    searchParams &&
    hasTimePeriodMigrationParams(searchParams)
  ) {
    return undefined;
  }

  return handler;
}
